input.content:
import fs from 'node:fs';
import path from 'node:path';
const [, , src, outDir] = process.argv;
const j = JSON.parse(fs.readFileSync(src, 'utf8'));
fs.mkdirSync(outDir, { recursive: true });
for (const o of j.code_objects) {
  const code = o.code.replace(/\r\n/g, '\n');
  fs.writeFileSync(path.join(outDir, `${o.OBJECT_NAME}.abap`), code);
  console.log(o.OBJECT_NAME, code.split('\n').length, 'lines');
}

