1943	/**
1944	 * Consistency checks between the ALV buttons and image-spec.buttonFlows —
1945	 * printed by render-md-images so a writer sees a missing flow before the
1946	 * spec ships. Navigation-only buttons opt out with `flow: false`.
1947	 */
1948	export function buttonSchemaWarnings(spec = {}) {
1949	  const warns = [];
1950	  const alv = spec.alv || {};
1951	  // A string button ("BACK") is shorthand for a label-only, navigation-only
1952	  // button: it cannot carry `flow: false`, so it is never asked for a flow.
1953	  const tag = (list, source, bar) => (Array.isArray(list) ? list : [])
1954	    .map(raw => ({ raw, b: normalizeButtons([raw])[0] }))
1955	    .filter(({ b }) => b && !b.sep && !b.std)
1956	    .map(({ raw, b }) => ({ ...b, source, bar, shorthand: typeof raw === 'string' }));
1957	  const buttons = [
1958	    ...tag(alv.screen?.buttons, 'pai', 'pai'),
1959	    ...tag(alv.toolbar, 'alv', 'grid'),
1960	    ...(Array.isArray(alv.panes) ? alv.panes.flatMap((p, i) => tag(p?.toolbar, 'alv', `pane${i}`)) : []),
1961	  ];
1962	  const where = (source) => (source === 'pai' ? 'PAI' : 'ALV');
1963	
1964	  // A code repeated within one bar is a mistake; the same code on two grids
1965	  // (each with its own REFRESH) is normal and shares one flow.
1966	  const seenButtons = new Set();
1967	  const seenInBar = new Set();
1968	  for (const b of buttons) {
1969	    if (!b.code) continue;
1970	    const barKey = `${b.bar}:${b.code}`;
1971	    if (seenInBar.has(barKey)) warns.push(`${where(b.source)} button "${b.code}" appears twice in the same toolbar`);
1972	    seenInBar.add(barKey);
1973	    seenButtons.add(flowKey(b.source, b.code));
1974	  }
1975	
1976	  const flows = Array.isArray(spec.buttonFlows) ? spec.buttonFlows : [];
1977	  const seenFlows = new Set();
1978	  flows.forEach((f, i) => {
1979	    const n = i + 1;
1980	    if (!f?.code) { warns.push(`buttonFlows #${n} has no code — it cannot be matched to a button`); return; }
1981	    const key = flowKey(f.source, f.code);
1982	    if (seenFlows.has(key)) warns.push(`buttonFlows #${n} "${f.code}" repeats an earlier ${where(f.source)} flow — only the first is used`);
1983	    seenFlows.add(key);
1984	    if (!seenButtons.has(key)) warns.push(`buttonFlows #${n} "${f.code}" (source "${f.source === 'pai' ? 'pai' : 'alv'}") has no matching button in ${f.source === 'pai' ? 'alv.screen.buttons' : 'alv.toolbar / panes[].toolbar'}`);
1985	    if (!isRenderableFlow(f)) warns.push(`buttonFlows #${n} "${f.code}" has no drawable flow — "flow" must be { nodes: [..at least one..], edges }`);
1986	  });
1987	
1988	  const index = buildFlowIndex(flows);
1989	  for (const b of buttons) {
1990	    if (!b.code || b.flow === false || b.shorthand) continue;
1991	    if (!index.has(flowKey(b.source, b.code))) {
1992	      warns.push(`${where(b.source)} button "${b.code}" has no usable buttonFlows entry — add its business flow, or set "flow": false if it only navigates (BACK / EXIT / REFRESH)`);
1993	    }
1994	  }
1995	  return warns;
1996	}
