2007	      'C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe',
2008	    ]
2009	    : platform() === 'darwin'
2010	      ? [
2011	        '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
2012	        '/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge',
2013	      ]
