1	#!/usr/bin/env node
2	/**
3	 * sc4sap PreToolUse hook — Prefer GetSqlQuery + Explicit Fields
4	 *
5	 * Credit-saving guard. Two rules:
6	 *
7	 *  1. `GetTableContents` returns every column for `SELECT * FROM <table>`.
8	 *     For real data needs, `GetSqlQuery` with an explicit field list is
9	 *     dramatically cheaper (rows × needed_columns vs rows × all_columns).
10	 *     Hook returns `permissionDecision: "ask"` so the user can confirm
11	 *     when a full snapshot really is wanted (e.g., schema discovery).
12	 *
13	 *  2. `GetSqlQuery` with `SELECT *` (or `SELECT TABLE.*`) defeats the
14	 *     purpose. Hook returns `ask` and asks the model to enumerate fields.
15	 *     COUNT/SUM/MIN/MAX/AVG aggregates are exempt — they don't expand.
16	 *
17	 *  Failure mode: fails OPEN on parse errors so a broken hook can't block
18	 *  legitimate development.
19	 */
20	
21	function readStdin() {
22	  return new Promise((done) => {
23	    let data = '';
24	    process.stdin.setEncoding('utf8');
25	    process.stdin.on('data', (c) => (data += c));
26	    process.stdin.on('end', () => done(data));
27	    process.stdin.on('error', () => done(data));
28	    setTimeout(() => done(data), 1500).unref?.();
29	  });
30	}
31	
32	function emit(decision, reason) {
33	  process.stdout.write(JSON.stringify({
34	    hookSpecificOutput: {
35	      hookEventName: 'PreToolUse',
36	      permissionDecision: decision,
37	      permissionDecisionReason: reason,
38	    },
39	  }));
40	  process.exit(0);
41	}
42	
43	function isSelectStar(sql) {
44	  // Strip leading whitespace + comments, normalize spaces.
45	  const norm = String(sql || '')
46	    .replace(/--[^\n]*\n/g, ' ')
47	    .replace(/\/\*[\s\S]*?\*\//g, ' ')
48	    .replace(/\s+/g, ' ')
49	    .trim();
